terrain::~terrain()
{
  tree->clear();
  delete tree;
  for (int i=regions.size(); --i>=0; )
  {
    delete regions[i];
  }
  regions.resize(0);
  sectors.resize(0);
  portal_list::iterator pli;
  for( pli = portals.begin(); pli != portals.end(); ++pli )
    delete *pli;
}
